   if !owner.history_input.is_some()&&owner.replacement_operation.is_none(){let index=replay.operation;let ledger=&mut self.log.envelope.vcs.edits;let source=owner.history_source.as_mut().unwrap();let input=&mut owner.history_input;let mut work=None;let receipt=funded_plan_retirement(control,grant,|effect|{let turn=source.advance(ledger,input,index+1,|edit|&edit.forwards[index],effect);work=Some(u64::try_from(effect.performed_work()).unwrap_or(u64::MAX));semio_framework_value::RetainedWorkPoll::Complete(turn).map_err(Into::into)})?;owner.preparation_work=work;owner.preparation_receipt=receipt;return Ok(ReplayStep::Pending(progress));}
